import { resolve } from "node:path";
import test from "node:test";
import { createServer } from "vite";

const root = new URL("../../", import.meta.url).pathname;

const server = await createServer({
  root,
  appType: "custom",
  configFile: false,
  logLevel: "silent",
  resolve: {
    alias: {
      "@/": `${resolve(root, "src")}/`,
    },
  },
  server: {
    middlewareMode: true,
  },
});

const {
  loadReaderMemos,
  MemoNotFoundError,
  normalizeMemoName,
} = await server.ssrLoadModule("/src/lib/reader.ts");

test("normalizeMemoName accepts a bare uid and a full memos/uid", () => {
  assert.equal(normalizeMemoName("alpha"), "memos/alpha");
  assert.equal(normalizeMemoName("memos/alpha"), "memos/alpha");
  assert.equal(normalizeMemoName("memos/abc-123_XYZ"), "memos/abc-123_XYZ");
});

test("normalizeMemoName rejects empty, malformed, and traversal values", () => {
  const invalid = [
    "",
    "users/1",
    "memos/../x",
    "memos/alpha/../..",
    "memos/alpha/..",
    "memos//alpha",
    "memos/alpha/",
    "memos/..",
    "alpha/.hidden",
    "a/b",
    "memos/alpha with space",
    "memos/\u0000alpha",
    "\u0000",
  ];
  for (const value of invalid) {
    assert.equal(normalizeMemoName(value), null, `expected ${JSON.stringify(value)} to be invalid`);
  }
});

test("loadReaderMemos uses the feed when memo is absent", async () => {
  const requested: string[] = [];
  globalThis.fetch = async (url) => {
    requested.push(String(url));
    return new Response(JSON.stringify({ memos: [] }), {
      status: 200,
      headers: { "content-type": "application/json" },
    });
  };

  const memos = await loadReaderMemos(new URLSearchParams());

  assert.deepEqual(requested, ["/api/v1/memos?pageSize=100"]);
  assert.deepEqual(memos, []);
});

test("loadReaderMemos fetches and parses a single bare Memo", async () => {
  let requested = "";
  globalThis.fetch = async (url) => {
    requested = String(url);
    return new Response(
      JSON.stringify({
        name: "memos/alpha",
        creator: "users/1",
        displayTime: "2023-11-14T22:13:20Z",
        content: "",
        nodes: [],
        resources: [],
      }),
      {
        status: 200,
        headers: { "content-type": "application/json" },
      },
    );
  };

  const memos = await loadReaderMemos(new URLSearchParams("memo=alpha"));

  assert.equal(requested, "/api/v1/memos/alpha");
  assert.equal(memos.length, 1);
  assert.equal(memos[0]!.name, "memos/alpha");
  assert.equal(memos[0]!.creator, "users/1");
  assert.ok(memos[0]!.displayTime instanceof Date);
});

test("loadReaderMemos throws MemoNotFoundError on 404", async () => {
  globalThis.fetch = async () => new Response("", { status: 404 });

  await assert.rejects(
    () => loadReaderMemos(new URLSearchParams("memo=missing")),
    (error: unknown) => error instanceof MemoNotFoundError && error.message === "Memo not found",
  );
});

